import sys
sys.dont_write_bytecode=True
import additional_pfp_domain_remaining_audit as a
n=a.read('_notes.json');n['controls'].extend(a.read('_ladder_stage_probes.json')['controls'])
def ev(p,*rs):
 p='pfp/domain/'+p;return {'path':p,'sha256':a.row(p)['sha256'],'lines':[list(x) for x in rs]}
for num,title,statement,es,ids in [
(90,'Ladder progression rule accepts a net collapse','H2 retains rates 0.9,0.1,0.2 as progression because it excludes only all-flat and strictly decreasing sequences. This does not establish accuracy rising then saturating.',[ev('pilots/certified_ladder.py',(469,499))],[112]),
(91,'Ladder statistics accept nonfinite and negative evidence','H3,H4,H5,H10 retain NaN inputs because ordered comparisons with NaN are false. DebtMetric accepts negative debt and H6 retains negative failure counts. These arithmetic summaries need finite/range/count premises before their verified prose is justified.',[ev('pilots/certified_ladder.py',(167,205),(502,614),(691,717))],[113]),
(92,'Ladder report can pass with no tested hypotheses','H12 retains an empty suite mapping and build_evaluation_report([]) returns PASS with total zero. The report has no H0-H13 completeness, uniqueness or status/refuted consistency condition. This is vacuous aggregation, not evidence of all ladder hypotheses.',[ev('pilots/certified_ladder.py',(744,767),(796,812))],[114]),
(93,'H0 trusts supplied outcome summary flags','A record with expected REFUSED, pass1 ACCEPTED, pass2 REFUSED, passes_match=True and cheat_accepted=False is retained. The rule never derives flags from statuses, so typed records alone cannot support the claimed deterministic rejection.',[ev('pilots/certified_ladder.py',(380,424))],[115]),
(94,'Equal control items can have unequal Python hashes','P0ControlItem compares payload dictionaries by mapping equality but hashes str(payload), which retains insertion order. Two equal dictionaries in different insertion orders yield equal objects with different hashes, violating Python hashed collection requirements. This is not a stable cryptographic digest.',[ev('pilots/certified_ladder.py',(221,246))],[116]),
(95,'Demo receipt permits contradictory success and authority fields','DemoRunReceipt accepts all_passed=True with a failed CheckResult and defaults terminal_status to Exact; authority_effect also accepts Granted. Schema construction does not reconcile checks, terminal or authority, so a receipt needs external host validation.',[ev('stages/demos.py',(48,60))],[117]),
(96,'Stage7 summary can contradict its validated host replay','WitnessReplay recomputes outcomes and ChallengeReplay enforces dense indices, but Stage7Response accepts a different demo_id, checked_count=0 and empty obstruction_indices while its host replay has one checked open obstruction. The wrapper does not bind summaries to its nested replay.',[ev('stages/stages.py',(431,495))],[118])]:n['findings'].append({'id':f'PFPDOMAIN-F{num:03}','title':title,'statement':statement,'evidence':[e['path'] for e in es],'source_evidence':es,'control_ids':[f'PFPDOMAIN-C{i:03}' for i in ids],'status':'confirmed_bounded_source_and_probe','limits':'Pure synthetic controls on unchanged read-vetted functions; no empirical experiment or downstream host integration claim.'})
a.write('_notes.json',n);a.report()
